L1: /**
L2:  * Claude plan usage fetcher.
L3:  *
L4:  * Reads the Claude Code OAuth access token from the macOS keychain on every
L5:  * call, queries Anthropic's (undocumented) usage endpoint, and normalizes the
L6:  * response. The token is held only in a local variable for the duration of the
L7:  * request: it is never cached, logged, returned, or included in error messages.
L8:  *
L9:  * This module never refreshes the OAuth token. Refreshing rotates the stored
L10:  * refresh token and can sign Claude Code out; Claude Code refreshes it on its
L11:  * own the next time it is used.
L12:  */
L13: import { execFile } from "node:child_process"
L14: 
L15: const KEYCHAIN_SERVICE = "Claude Code-credentials"
L16: const USAGE_URL = "https://api.anthropic.com/api/oauth/usage"
L17: const BETA_HEADER = "oauth-2025-04-20"
L18: const REQUEST_TIMEOUT_MS = 10_000
L19: 
L20: export interface UsageWindow {
L21:   readonly key: string
L22:   readonly label: string
L23:   /** 0-100 */
L24:   readonly utilization: number
L25:   /** Epoch ms, or null when the window has not started (no usage yet, endpoint returns resets_at: null). */
L26:   readonly resetsAt: number | null
L27: }
L28: 
L29: export interface ExtraUsage {
L30:   readonly enabled: boolean
L31:   /** In major currency units (e.g. dollars), already scaled from the endpoint's minor units. */
L32:   readonly usedCredits: number
L33:   /** In major currency units (e.g. dollars), already scaled from the endpoint's minor units. */
L34:   readonly monthlyLimit: number | null
L35:   readonly currency: string
L36:   readonly spendLimitReached: boolean
L37: }
