L129: /** Reads the keychain, calls the endpoint, and returns a normalized result. Never throws. */
L130: export async function fetchUsage(): Promise<UsageResult> {
L131:   if (process.platform !== "darwin") {
L132:     return { status: "error", message: "macOS only: credentials are read from the macOS keychain" }
L133:   }
L134: 
L135:   let token: string
L136:   try {
L137:     const creds = await readCredentials()
L138:     if (creds.expiresAt <= Date.now()) {
L139:       return { status: "stale", message: "stale — token refreshes on next Claude use" }
L140:     }
L141:     token = creds.accessToken
L142:   } catch (error) {
L143:     return { status: "error", message: (error as Error).message }
L144:   }
L145: 
L146:   let response: Response
L147:   try {
L148:     response = await fetch(USAGE_URL, {
L149:       headers: { Authorization: `Bearer ${token}`, "anthropic-beta": BETA_HEADER },
L150:       signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
L151:     })
L152:   } catch (error) {
L153:     const name = (error as Error).name
L154:     return {
L155:       status: "error",
L156:       message: name === "TimeoutError" ? "usage request timed out" : "usage request failed (network)",
L157:     }
L158:   } finally {
L159:     token = ""
L160:   }
L161: 
L162:   if (response.status === 401) {
L163:     return { status: "stale", message: "stale — token rejected (401); refreshes on next Claude use" }
L164:   }
L165:   if (response.status === 429) {
L166:     const retryAfter = Number(response.headers.get("retry-after"))
L167:     return {
L168:       status: "rate_limited",
L169:       message: "rate limited by usage endpoint",
L170:       retryAfterMs: Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter * 1000 : undefined,
L171:     }
L172:   }
L173:   if (!response.ok) {
L174:     return { status: "error", message: `usage endpoint returned HTTP ${response.status}` }
L175:   }
L176: 
L177:   let body: unknown
L178:   try {
L179:     body = await response.json()
L180:   } catch {
L181:     return { status: "error", message: "usage endpoint returned non-JSON body" }
L182:   }
L183: 
L184:   try {
L185:     return parseUsage(body)
L186:   } catch (error) {
L187:     return { status: "error", message: (error as Error).message }
L188:   }
L189: }

